<script setup lang="ts">
interface UserItem { id: string, username: string, display_name: string, role: string, permissions: string[], enabled: boolean }
interface CommentItem { id: string, photoId: string, body: string, status: string, hiddenReason: string | null }
const api = useManageApi(); const users = ref<UserItem[]>([]); const comments = ref<CommentItem[]>([]); const error = ref(''); const invite = ref('')
const permissions = ['profile.self.update','photo.create','photo.publish','story.create','story.publish','comment.create','comment.moderate']
const selectedInvitePermissions = ref(['profile.self.update','photo.create','story.create','comment.create'])
const publishMessage = ref('')
useHead({ title: '账号与审核 · McAlbum' })
onMounted(async () => { if (!await api.restore()) return; if (api.session.value?.user.role !== 'admin') return navigateTo('/manage'); [users.value, comments.value] = await Promise.all([api.request<UserItem[]>('/admin/users'), api.request<CommentItem[]>('/admin/comments')]) })
async function createInvite() { try { const result = await api.request<{ code: string }>('/admin/invitations', { method: 'POST', body: { expires_in_hours: 72, permissions: selectedInvitePermissions.value } }); invite.value = result.code } catch (caught) { error.value = api.errorMessage(caught) } }
async function savePermissions(user: UserItem) { try { const result = await api.request<UserItem>(`/admin/users/${user.id}/permissions`, { method: 'PUT', body: { permissions: user.permissions } }); user.permissions = result.permissions } catch (caught) { error.value = api.errorMessage(caught) } }
async function toggleUser(user: UserItem) { try { await api.request(`/admin/users/${user.id}/status`, { method: 'PUT', body: { enabled: !user.enabled } }); user.enabled = !user.enabled } catch (caught) { error.value = api.errorMessage(caught) } }
async function moderate(comment: CommentItem) { const hidden = comment.status !== 'hidden'; const reason = hidden ? window.prompt('隐藏原因（可留空）') : null; try { const updated = await api.request<Record<string, string | null>>(`/comments/${comment.id}/moderate`, { method: 'POST', body: { hidden, reason } }); comment.status = String(updated.status); comment.hiddenReason = updated.hidden_reason ?? null } catch (caught) { error.value = api.errorMessage(caught) } }
async function rebuild() { error.value = ''; publishMessage.value = '正在生成公开快照……'; try { const result = await api.request<{ counts: Record<string, number> }>('/admin/publish', { method: 'POST' }); publishMessage.value = `快照已生成：${result.counts.photos} 张照片、${result.counts.stories} 篇作品集。` } catch (caught) { publishMessage.value = ''; error.value = api.errorMessage(caught) } }
</script>

<template><ManageShell><header class="manage-heading"><p class="section-kicker">管理员</p><h1>账号、能力与评论审核</h1><p>权限只从固定能力中选择；邀请码只展示一次，请通过可信渠道发送。</p></header><ManageNotice v-if="error" kind="error">{{ error }}</ManageNotice><section class="manage-admin-section"><h2>生成归档快照</h2><p>公开内容刷新时已经自动读取最新发布数据；这里只用于同步 JSON、更新 SEO 页面并生成可独立保存的静态快照。</p><button class="manage-primary" type="button" @click="rebuild">同步并生成快照</button><ManageNotice v-if="publishMessage" kind="success">{{ publishMessage }}</ManageNotice></section><section class="manage-admin-section"><h2>创建邀请码</h2><div class="manage-permission-grid"><label v-for="permission in permissions" :key="permission"><input v-model="selectedInvitePermissions" type="checkbox" :value="permission">{{ permission }}</label></div><button class="manage-primary" type="button" @click="createInvite">生成 72 小时邀请码</button><ManageNotice v-if="invite" kind="success">请立即保存：<code>{{ invite }}</code></ManageNotice></section><section class="manage-admin-section"><h2>账号权限</h2><article v-for="user in users" :key="user.id" class="manage-user"><header><div><strong>{{ user.display_name }}</strong><span>@{{ user.username }} · {{ user.role }}</span></div><button v-if="user.role !== 'admin'" type="button" @click="toggleUser(user)">{{ user.enabled ? '停用账号' : '恢复账号' }}</button></header><div v-if="user.role !== 'admin'" class="manage-permission-grid"><label v-for="permission in permissions" :key="permission"><input v-model="user.permissions" type="checkbox" :value="permission">{{ permission }}</label></div><button v-if="user.role !== 'admin'" type="button" @click="savePermissions(user)">保存权限</button></article></section><section class="manage-admin-section"><h2>最新评论</h2><p v-if="comments.length === 0">还没有玩家评论。</p><article v-for="comment in comments" :key="comment.id" class="manage-comment"><div><span class="manage-status" :data-status="comment.status">{{ comment.status }}</span><p>{{ comment.body }}</p><small>照片：{{ comment.photoId }}</small></div><button type="button" @click="moderate(comment)">{{ comment.status === 'hidden' ? '恢复' : '隐藏' }}</button></article></section></ManageShell></template>
